'use strict';
const {course}=require('./data-helper');
const specs=[
{id:'dbf-question',comps:['m1.c1'],title:'Turn a vague request into an answerable decision question',intro:'A shop owner asks, “Why are sales bad?” An analyst first clarifies the decision rather than immediately producing charts. A useful question defines the outcome, population, period, comparison and action the evidence can support.',sections:[['Specify what the decision needs','Ask who will use the answer and what they can change: staffing, stock, pricing or marketing. Replace vague words such as bad with a measurable outcome and benchmark. “How did completed-order revenue per open day change this month versus comparable days last month?” is more testable than “Are we successful?”','Write scope, definitions and exclusions before extraction. Revenue, profit, order count and conversion describe different things. Distinguish a descriptive question (what changed), diagnostic association (what differs), predictive question (what may happen) and causal question (what would changing an action do).'],['Agree on an analytical contract','Document the decision, owner, data needed, time boundary, comparison, expected deliverable and limits. A request can be valuable even when the answer is that current records cannot identify its cause. Avoid promising causal explanations from an uncontrolled comparison.','The example builds a small question contract and checks required fields. It verifies completeness of a toy specification, not that the chosen metric or comparison is correct for a real business. Stakeholder review supplies that missing judgment.']],problem:'Represent an analytical question as a checkable specification.',steps:['Record the decision and metric.','State population, period and comparison.','Check that required fields are present and nonempty.'],code:'request={"decision":"staffing","metric":"completed orders per open day","population":"store-7","period":"2026-10","comparison":"comparable September weekdays"}\nrequired={"decision","metric","population","period","comparison"}\nprint(required.issubset(request))\nprint(all(request[k].strip() for k in required))',expect:'True\nTrue',limit:'Field presence is only a structural check. It does not validate causal identification, metric suitability or stakeholder agreement.',mistakes:['Starting with available charts can miss the actual decision.','A before/after difference alone does not prove what caused it.'],takeaways:['Make the question operational before querying.','State what the available evidence cannot answer.'],practice:[
['Which question is more operational?','Orders/day vs prior month','Are things bad?','Is our business good?','Why is everything wrong?','A defined outcome, period and comparison make the first question answerable and reviewable.'],
['What should be clarified before choosing a chart?','The supported decision','The favorite chart color','The export filename','The monitor width','The decision determines which evidence and definitions are useful.'],
['Does a sales decline alone identify its cause?','No','Yes by subtraction','Only if rounded','Only if plotted','Many concurrent changes or selection effects can explain a descriptive decline.'],
['A manager asks for revenue but will decide staffing. What should the analyst clarify?','Staffing-relevant outcome','Only the logo placement','Only the report page count','Only the spreadsheet font','The measurement must support an actionable decision; revenue may not capture service workload directly.'],
['Two teams disagree whether refunds reduce revenue. What is needed?','Shared metric meaning','A larger chart','A random team choice','A different sort order','Definitions and exclusions must be aligned before results can be compared.'],
['A dataset cannot distinguish marketing effects from seasonality. What is appropriate?','Report the identification limit','Invent a causal percentage','Remove the season field','Declare marketing irrelevant','Acknowledge what the design/data cannot identify instead of manufacturing certainty.'],
['A request lacks a time window. What is the practical risk?','Incomparable scopes','Automatic causal bias removal','Guaranteed identical totals','A missing arithmetic function','Different reporting windows can produce different answers to the same vague request.']
],formal:[
['What is a primary purpose of analytical scoping?','Connect evidence to a decision','Maximize chart count','Avoid every assumption','Guarantee a preferred result','A scoped question specifies what decision the evidence will inform and what can be answered.'],
['Which is a descriptive question?','How many orders completed last week?','What would a price change cause?','Which intervention guarantees growth?','What caused every cancellation?','Counting observed outcomes describes what happened without itself identifying intervention effects.'],
['What makes a comparison interpretable?','Aligned definitions and periods','Different units in each group','Only a decorative title','Unrecorded exclusions','Comparable scope and definitions are necessary to interpret differences meaningfully.'],
['A restaurant asks whether service is slow. What should an analyst define first?','A service-time target','Only a bar-chart layout','Only the output file type','Only the restaurant slogan','An operational outcome, population and meaningful benchmark turn slow into a measurable question.'],
['A retailer wants profit but provides only sales totals. What gap matters?','Cost information','Only customer names','Only chart colors','Only row ordering','Profit depends on revenue minus relevant costs; sales alone cannot establish it.'],
['A department requests a causal explanation from monthly totals only. What must be stated?','The limits of the design','A guaranteed causal driver','A fictional control group','A preferred intervention score','Aggregated observational totals may describe change without identifying why it occurred.'],
['A report compares this week’s seven days to last week’s five open days. What needs review?','Exposure/comparison scope','Only the title case','Only the currency symbol','Only the table border','Different exposure can change totals even if daily performance is unchanged.'],
['A stakeholder changes the decision from staffing to pricing. What should happen?','Revisit question and metric','Keep every old assumption silently','Only rename the report','Discard all data automatically','The useful outcome, comparison and required evidence can change with the decision.'],
['A team chooses a metric because it produces the desired headline. What is at risk?','Decision integrity','The existence of numbers','The ability to sum rows','The file format','Outcome-driven metric selection can misrepresent the question and encourage misleading conclusions.'],
['An analysis contract has every field but an irrelevant metric. What follows?','Structure alone is insufficient','The decision is validated','The question is causal','The report must be published','A complete specification still requires substantive review of relevance, measurement and assumptions.']
]},
{id:'dbf-stakeholders',comps:['m1.c2'],title:'Identify the decision owner, users and affected people',intro:'A hospital operations report may be requested by finance, used by scheduling staff and affect patients. These are different stakeholder roles with different information needs and authority.',sections:[['Map accountability and action','Identify the decision owner who can authorize an action, the operational users who will execute it, data stewards who explain sources and affected groups who bear consequences. Clarify whether the analyst is recommending, deciding or supplying evidence. An audience list is not a permission grant.','Ask what each stakeholder needs to know and when. A scheduler may need daily queue counts, while executives need trends and uncertainty. Agree on useful granularity and delivery timing rather than distributing every available record to everyone.'],['Translate needs into safe deliverables','Prefer the minimum detail necessary for the decision. Aggregated outcomes may support planning without exposing personal records. Data access should follow the organization’s actual authorization and privacy policy; convenience is not sufficient justification for disclosure.','The fixture associates each decision with a named owner role and checks for missing ownership. It uses synthetic roles only and cannot authorize real staff. Its purpose is to make an accountability gap visible before a report is used.']],problem:'Check whether every proposed action has an accountable owner.',steps:['List the actions under review.','Map each to its decision owner.','Report actions with no owner before work proceeds.'],code:'actions=["adjust_staff","change_price","publish_report"]\nowners={"adjust_staff":"operations","change_price":"commercial"}\nprint([a for a in actions if a not in owners])\nprint(len(set(owners.values())))',expect:"['publish_report']\n2",limit:'This checks a synthetic ownership mapping. Real authority, approvals and privacy obligations require the organization’s reviewed policies.',mistakes:['A report recipient is not automatically authorized to access underlying records.','Producing evidence does not give an analyst authority to make every operational decision.'],takeaways:['Separate decision ownership, execution and affected groups.','Design information delivery around purpose and permissions.'],practice:[
['Who is the decision owner?','The accountable role','Anyone who opens a chart','Every database user','Only the report designer','Decision ownership concerns authority/accountability for the action rather than merely viewing evidence.'],
['Does being a report audience member grant raw-data access?','No','Yes universally','Only for large reports','Only if emailed','Access must follow authorized purpose and policy, not audience membership alone.'],
['Why identify affected stakeholders?','To understand consequences','To force unanimous outcomes','To remove all tradeoffs','To avoid defining metrics','People affected by the decision can reveal harms, constraints and context absent from a requester’s view.'],
['Finance and scheduling need different report detail. What is appropriate?','Purpose-specific views','Every raw patient row to both','One unexplained total only','Randomly chosen columns','Views should support each authorized decision while minimizing unnecessary sensitive detail.'],
['A proposed action has no accountable owner. What should be resolved?','Decision responsibility','Only chart size','Only data encoding','Only naming style','An analysis can be unused or misapplied when no one owns the resulting decision.'],
['A data steward explains that a status field changed meaning. Why involve them?','They supply source context','They can approve every decision','They replace all users','They guarantee every model','Source owners help interpret lineage and changes, while decision authority and analytical validation remain separate.'],
['A manager wants all identifiers in a planning chart without a purpose. What should be reviewed?','Necessary disclosure','Only font readability','Only export compression','Only row sorting','The deliverable should expose only justified authorized detail needed for the planning task.']
],formal:[
['What distinguishes an operational user from a decision owner?','Execution versus decision accountability','They always have identical authority','Only their email format','Only their table preference','Roles can overlap, but execution needs and authority to decide should be clarified separately.'],
['What can a data steward contribute?','Field meaning/lineage','Guaranteed business success','Automatic causal proof','Universal access permission','A steward can explain source definitions, collection and changes within the actual governance arrangement.'],
['What is a useful report-design question?','The audience’s action','Which chart is fashionable?','How many colors fit?','Can every raw row be exported?','Deliverables should support a defined action and authorized audience need.'],
['A logistics analyst recommends route changes but cannot approve them. What should the report clarify?','Recommendation and approval roles','That recommendations are orders','That charts grant authority','That no owner is needed','The report should distinguish evidence/recommendation from the person authorized to act.'],
['A school dashboard is sent to all staff with private student details. What needs review?','Purpose and access scope','Only column alignment','Only PDF page breaks','Only sorting speed','Recipients should receive only data appropriate to their authorized role and decision purpose.'],
['A finance report arrives after the budget decision. Which requirement was missed?','Decision timing','Only numerical precision','Only the title font','Only the chart legend','Evidence must arrive within the decision window to be actionable.'],
['A service change benefits managers but harms vulnerable customers. What was potentially missing?','Affected-group perspective','Only another summary total','Only a larger sample file','Only the executive signature','Stakeholder analysis should consider who experiences the consequences, including groups absent from the requester list.'],
['Two departments believe the other owns an intervention. What helps?','Accountable ownership','More dashboard tabs','Only another data export','A renamed metric','A documented action/owner mapping prevents responsibility gaps and conflicting assumptions.'],
['A report gives an executive every transaction when monthly totals suffice. What principle applies?','Data minimization','Mandatory raw-data sharing','Random suppression','Unlimited access by seniority','The necessary level of detail should follow authorized purpose, not the maximum available data.'],
['A stakeholder map is complete. What does it not automatically establish?','Record authorization','Who the listed roles are','That actions were named','That audiences were considered','A planning artifact does not replace authenticated access controls or the organization’s actual governance policy.']
]},
{id:'dbf-evidence',comps:['m1.c1','m1.c2'],title:'Choose evidence and communicate what it can support',intro:'An analyst’s result should let a decision owner see both the answer and the path used to reach it. Transparent assumptions are especially important when data is incomplete or conflicting.',sections:[['Build a chain from question to evidence','Map each question to the fields, population, time window and calculation required. Trace each output to a source and transformation. Separate observed facts from interpretations and recommendations, and record assumptions such as how canceled orders or missing timestamps are treated.','Assess timeliness, completeness, consistency and measurement fit. A source can be precise yet irrelevant, current yet incomplete, or authoritative for one purpose but not another. Prefer corroborating sources when definitions can be reconciled; do not average conflicting totals without understanding the mismatch.'],['Communicate uncertainty and next actions','State the result in decision language, show key comparisons and explain material limitations. A useful answer can be a bounded conclusion with a next data-collection step. Avoid disguising unknown outcomes as zero or presenting a speculative explanation as an observed cause.','The worked example separates known outcomes from missing ones and reports a coverage measure. It does not impute missing results. Whether a complete-case average represents the target population depends on why those outcomes are missing.']],problem:'Report an observed outcome rate together with data coverage.',steps:['Separate observed values from missing values.','Compute the rate only on its declared observed denominator.','Report coverage so the reader sees the missing population.'],code:'outcomes=[1,0,None,1,None]\nknown=[v for v in outcomes if v is not None]\nprint(sum(known)/len(known))\nprint(len(known)/len(outcomes))',expect:'0.6666666666666666\n0.6',limit:'The observed rate is conditional on known outcomes. It does not estimate the missing cases or establish that missingness is random.',mistakes:['Missing is not automatically zero.','An unexplained disagreement between sources is not solved by averaging their totals.'],takeaways:['Maintain a traceable evidence chain.','Communicate coverage and limits alongside estimates.'],practice:[
['What should connect a reported number to its origin?','Data lineage','Only a chart title','Only a file icon','Only a color palette','Lineage records sources and transformations so a result can be explained and reproduced.'],
['Should missing outcomes always be coded as zero?','No','Yes by default','Only for large tables','Only if a mean is needed','Missing means unknown under the collection process; zero is a substantive observed value.'],
['What is a defensible distinction in a report?','Observation versus interpretation','Large font versus small font only','CSV versus PDF only','Odd versus even row ids','Separating evidence from inference prevents assumptions from being presented as direct observations.'],
['Only 60% of cases have known outcomes. What should accompany their success rate?','Coverage and missingness limits','A claim of complete evidence','Only the rounded rate','A hidden missing-count field','The rate conditions on observed outcomes and may not represent cases with unknown results.'],
['Two systems report different revenue totals. What should happen before combining them?','Reconcile definitions and scope','Average immediately','Choose the larger result','Delete the older source blindly','Differences can reflect status rules, timing, currency or duplication rather than interchangeable estimates.'],
['A decision owner needs an action tomorrow but the data is a year old. What is in question?','Timeliness and relevance','Only the file extension','Only the arithmetic syntax','Only display contrast','Old evidence may not describe the current population or operating conditions.'],
['A report cannot distinguish two explanations. What is a useful next step?','Targeted data collection/design','Select the preferred story','Omit every limitation','Invent missing observations','Acknowledge uncertainty and identify evidence capable of separating the competing explanations.']
],formal:[
['What is a reproducible analytical result?','One with traceable inputs and steps','One with many charts','One that always agrees with management','One with no assumptions','Documented sources, definitions and transformations allow another reviewer to follow the calculation.'],
['What does completeness describe?','Availability of required data','Only file compression','Only decimal precision','Guaranteed truth of every value','Completeness concerns whether needed fields/cases are present, which differs from accuracy or relevance.'],
['What should a limitation statement do?','Bound the supported conclusion','Cancel every useful finding','Guarantee no error','Replace all evidence','A limitation tells readers where assumptions, missingness or design constrain inference.'],
['A warehouse marks a late-delivered record as unknown. An analyst converts it to on-time=0. What needs review?','Unknown versus failure','Only numeric storage size','Only row sorting','Only dataset title','Unknown delivery status is not necessarily a known late outcome; coding rules affect the metric meaning.'],
['A dashboard gives an exact-looking number from uncertain source matching. What should be visible?','Matching and coverage','Only more decimal places','Only the largest total','Only a confident title','Precision of formatting does not eliminate uncertainty in linkage, source coverage or definitions.'],
['A report says marketing caused sales growth using one before/after total. What is unsupported?','The causal attribution','That the totals differ','That a period was named','That revenue can be summed','A temporal comparison alone cannot isolate marketing from other changing factors.'],
['An analyst documents a transformation but loses its source version. What is impaired?','Reproducibility','The existence of the output','The concept of a metric','All arithmetic rules','Reproducing results requires knowing the exact inputs as well as the processing steps.'],
['A management summary hides a major excluded region. What is misleading?','Population coverage','Only the chart placement','Only the page numbering','Only the column width','A scope exclusion materially affects who the estimate describes and must be disclosed.'],
['A source is official for invoices but not shipment events. What should be assessed?','Fitness for the question','Only organizational seniority','Only file size','Only whether it is structured','Source authority is purpose-specific; billing records may not measure physical delivery behavior correctly.'],
['A reviewer cannot distinguish observed facts from recommendations. What should be revised?','Evidence versus inference','Only the logo resolution','Only the row count','Only the export password','Clear distinctions help decision owners evaluate how assumptions and judgment lead from data to proposed action.']
]},
{id:'dbf-grain',comps:['m2.c1'],title:'Define record grain, identifiers and measurement units',intro:'A sales table may contain one row per order, one row per line item or one row per daily store total. These are different grains. An analyst must understand what one row represents before counting or joining it.',sections:[['Type and grain answer different questions','A categorical value identifies a class, an ordinal value has a meaningful order and a quantitative measure supports defined arithmetic. An identifier may contain digits but averaging customer ids has no business meaning. Units such as cents, dollars, kilograms or minutes belong in field definitions.','Grain states the entity/event/time level of a row. A customer can have many orders and each order many lines. Counting line-item rows as orders overstates order count. Summing an order total repeated on every line duplicates revenue. Keys and uniqueness tests help check a stated grain.'],['Joins can change the denominator','A one-to-many join expands rows. Before merging sources, state expected cardinality and test it. Missing matches can remove entities in an inner join; duplicate keys can multiply values. Validate counts and aggregate measures before and after joining.','The fixture has two orders and three lines. It contrasts line count, distinct order count and a duplicated header-total sum. It uses exact integer cents and demonstrates why grain must govern calculations, not merely whichever rows a query returns.']],problem:'Inspect line-item grain without duplicating order-level revenue.',steps:['Count line rows and distinct order ids separately.','Look up each order-level total only once.','Contrast the repeated-header sum with the correct total.'],code:'totals={"o1":1000,"o2":500}\nlines=[("o1","a"),("o1","b"),("o2","c")]\nprint(len(lines),len({o for o,p in lines}))\nprint(sum(totals[o] for o,p in lines))\nprint(sum(totals.values()))',expect:'3 2\n2500\n1500',limit:'The example assumes authoritative unique header totals. Real joins need key, completeness, currency and status validation as well.',mistakes:['Numeric-looking identifiers are not continuous measures.','Summing repeated header totals across line rows duplicates revenue.'],takeaways:['Define row grain and units before aggregation.','Validate join cardinality and key uniqueness.'],practice:[
['What does table grain describe?','What one row represents','The file’s byte size','Only the column count','Only decimal precision','Grain identifies the entity/event/time level represented by each row.'],
['Should customer identifiers be averaged as a business measure?','No','Yes if numeric','Only if unique','Only if sorted','Identifiers label entities; their numeric encoding does not define meaningful magnitude or distance.'],
['Two orders have three line items. How many orders are represented?','2','3','5','1','Distinct order identifiers determine order count at order grain.'],
['An order total appears on every joined line. What does summing it risk?','Double counting','Automatic deduplication','A guaranteed zero total','Correct order grain','A one-to-many join repeats order-level measures, so naive summation inflates them.'],
['One source stores cents and another dollars. What must happen before summing?','Unit alignment','Only row sorting','Only renaming ids','Only matching colors','Values need a shared currency/unit convention before arithmetic combines them.'],
['A lookup key unexpectedly has duplicates. What should be reviewed before joining?','Expected cardinality','Only the CSV separator','Only table display width','Only character encoding','Duplicate lookup matches can multiply rows and distort counts or sums.'],
['A category has labels low, medium and high. What kind of property is present?','An ordinal order','A known equal interval','A currency amount','A unique continuous measure','The labels have order, but equal spacing or meaningful multiplication is not implied.']
],formal:[
['Which field is primarily an identifier?','Invoice number','Invoice amount','Delivery duration','Package mass','Invoice numbers distinguish records; their encoding does not make them quantitative measures.'],
['What is one-to-many cardinality?','One-to-many matching','Every row matches none','Every table has one column','Two measures share units','A parent entity may have multiple related child records.'],
['What must a unique key do at the declared grain?','Identify at most one row','Always be a small integer','Carry the highest amount','Equal every other key','A uniqueness constraint/test checks that the chosen key is not repeated at the stated row level.'],
['A store counts item rows as purchases. What should be corrected?','The aggregation grain','Only the chart color','Only the column spelling','Only the export format','Multiple items can belong to one purchase, so transaction count requires transaction-level identity.'],
['A join triples revenue without new orders. Which issue is plausible?','Row multiplication','Improved profitability','Automatic inflation correction','A causal marketing effect','Unexpected multiplicity can repeat measures rather than represent real additional revenue.'],
['A file mixes duration seconds and minutes in one unlabeled column. What is missing?','A consistent unit contract','Only a larger integer type','Only sorted timestamps','Only a unique id','Without known units, magnitudes cannot be compared or aggregated meaningfully.'],
['An inner join removes orders lacking a customer match. What should be reported?','Match coverage and exclusions','Only the remaining total','That no orders were lost','That joins preserve every row','Join type and matching quality can change the population represented in the result.'],
['A survey encodes satisfaction as 1,2,3,4. What should not be assumed automatically?','Equal numerical spacing','A category ordering','The existence of responses','That four labels exist','Ordinal encoding provides order but does not itself establish an interval-scale measurement.'],
['A unique-order report has repeated order ids. What should happen?','Check the grain','Average the identifiers','Ignore duplicates always','Rename the table only','Repeated keys contradict a one-row-per-order claim and can distort downstream metrics.'],
['A dashboard combines customer-level and event-level data. What must every measure preserve?','Entity/denominator meaning','Only a shared filename','Only the total column count','Only a date display style','Mixed-grain joins require deliberate aggregation and population handling to avoid misleading denominators.']
]},
{id:'dbf-sources',comps:['m2.c2'],title:'Understand operational sources and collection limitations',intro:'Business data is produced by systems designed for different jobs: billing, support, web interaction and inventory. A convenient export may record a workflow step rather than the real-world outcome an analyst needs.',sections:[['Source purpose shapes what is observed','Transactions capture completed system actions under application rules. Event logs record instrumented occurrences, potentially with retries, missing clients or changed schemas. Surveys measure answers under a recruitment and wording process. External datasets carry their own collection scope, time and licensing limitations.','Identify the system of record for each concept and distinguish event time from ingestion time. A payment authorization is not necessarily a settled payment; a page view is not a distinct person; a shipped status may not prove physical delivery. Source semantics should be checked with responsible stewards.'],['Quality has multiple dimensions','Check validity, completeness, uniqueness, consistency, timeliness and accuracy relative to the question. A valid date can still be the wrong date. A complete field can contain systematically incorrect values. Late-arriving events can revise prior periods, so snapshot/cutoff rules matter.','The fixture removes duplicate event deliveries by a stable event id and exposes a missing event time. It does not treat deduplication as proof that every real event was observed or that identifiers are trustworthy. Real ingestion needs versioned contracts and reconciliation.']],problem:'Inspect duplicated and incomplete synthetic event records.',steps:['Separate event delivery rows from unique event ids.','Count repeated deliveries.','Identify missing event-time fields without inventing values.'],code:'events=[{"id":"e1","at":"2026-10-01"},{"id":"e1","at":"2026-10-01"},{"id":"e2","at":None}]\nprint(len(events),len({e["id"] for e in events}))\nprint(sorted({e["id"] for e in events if e["at"] is None}))',expect:"3 2\n['e2']",limit:'Stable ids permit this illustrated duplicate check. It cannot discover unlogged real events or establish the correctness of supplied times.',mistakes:['A log row is not necessarily a distinct person or business event.','Ingestion time is not automatically the time the event occurred.'],takeaways:['Learn why a source exists and what it measures.','Record quality limitations and late-data rules.'],practice:[
['Which statement best describes event logs?','They record instrumented events','They necessarily cover every real action','They always identify distinct people','They cannot contain retries','Logs reflect instrumentation and delivery behavior, including possible missing or repeated events.'],
['Is a payment authorization always a settled payment?','No','Yes by definition','Only if stored as text','Only if the amount is positive','Authorization and settlement are different workflow states with different business meaning.'],
['What differs between event time and ingestion time?','Occurrence versus receipt','Only date formatting','Only timezone spelling','Nothing in every system','An event can occur before it is received, processed or stored.'],
['Three deliveries contain two unique stable event ids. What may be present?','A repeated delivery','Three distinct people necessarily','A zero event count','Automatic causal evidence','Repeated delivery of the same logical event can produce multiple stored rows.'],
['A date field is syntactically valid but describes billing rather than delivery. What is wrong?','Measurement relevance','The date parser necessarily','The existence of a timestamp','The ability to sort dates','Validity of representation does not guarantee the field measures the event relevant to the question.'],
['Late events revise last month’s totals. What should be documented?','Cutoff/revision policy','Only the chart palette','Only table dimensions','Only the exporter name','Reports need explicit event/ingestion windows and rules for later revisions.'],
['An external dataset has unknown recruitment methods. What remains uncertain?','Coverage and selection','Whether rows can be counted','Whether columns exist','Whether text can be stored','Collection design determines what population claims the data can support.']
],formal:[
['What is a system of record?','A defined source of truth','Any newest spreadsheet','Every public website','Only the largest table','Authority is tied to a business concept and governance context, not simply size or recency.'],
['What does timeliness assess?','Purpose-relevant freshness','Only whether values are numeric','Only if keys are unique','Guaranteed causal relevance','Timeliness concerns when observations become available and whether they suit the decision window.'],
['Can a nonmissing field still be inaccurate?','Yes','No by definition','Only if stored in JSON','Only for negative numbers','Completeness and accuracy are different quality dimensions.'],
['A mobile app loses events while offline. What should an analyst avoid claiming?','Complete behavior coverage','That received rows exist','That recorded ids can be counted','That a known window was used','Unobserved offline behavior can make the logs an incomplete view of the target activity.'],
['A support system marks tickets resolved automatically after inactivity. What needs clarification?','Status semantics','Only status text length','Only the ticket-id prefix','Only the chart legend','Administrative resolution may not mean the customer’s underlying problem was solved.'],
['A retailer counts retries as new purchases. What source property was missed?','Delivery/event identity','Only the currency symbol','Only the page layout','Only alphabetical sorting','Repeated system deliveries must be distinguished from distinct business actions.'],
['A dataset refresh changes prior totals. What supports reproducibility?','Snapshots and cutoffs','Only the latest total','Only a larger spreadsheet','Only a renamed chart','Recorded source versions and temporal rules let reviewers reconstruct what was known for a report.'],
['A valid positive amount is in the wrong currency. Which issue remains?','Semantic consistency','A solved correctness problem','Only missingness','Only key uniqueness','A valid numeric range does not establish compatible currency meaning.'],
['A web view is treated as a person in a reach report. What should be reviewed?','The counting unit','Only browser color settings','Only numeric field width','Only the date separator','One person can generate many views and devices; events and distinct entities are different grains.'],
['A source is called authoritative. Does that remove all analytical checks?','No, quality still matters','Yes, every field is perfect','Only if the file is signed','Only if rows are unique','Authority for a concept does not guarantee complete, current, correctly transformed evidence for every question.']
]},
{id:'dbf-quality',comps:['m2.c1','m2.c2'],title:'Make a small data contract and validate it defensively',intro:'A data contract records what a dataset promises: grain, fields, types, units, permitted values and update behavior. Validation makes some violations visible without pretending every plausible record is true.',sections:[['Translate assumptions into checks','For a one-row-per-order dataset, test unique order ids, supported statuses, known currency units and valid event times. Define nullable fields and distinguish empty strings, missing values and substantive zeros. Numeric range checks should reflect the domain rather than convenient arbitrary thresholds.','Keep raw evidence and validation findings separate. Reject, quarantine or flag records according to reviewed policy; silently dropping difficult cases can bias a report. A validation pass means the declared checks passed, not that all real-world facts are correct.'],['Track changes and usable coverage','Schema changes can alter types, units or status meanings without causing a parse error. Version definitions and coordinate producer/consumer updates. Monitor both rejected records and successfully processed coverage so failures do not disappear inside a smaller denominator.','The fixture checks duplicate keys, allowed statuses and nonnegative integer cents. It deliberately excludes booleans as amounts because Python bool is an int subclass. It reports errors rather than rewriting records, demonstrating a defensive boundary between evidence and correction.']],problem:'Validate a synthetic order record against explicit field rules.',steps:['Check identity uniqueness across rows.','Validate status and integer-cent representation.','Collect error categories without modifying evidence.'],code:'rows=[{"id":"o1","status":"paid","cents":100},{"id":"o1","status":"unknown","cents":True}]\nseen=set();errors=[]\nfor r in rows:\n    if r["id"] in seen: errors.append("duplicate_id")\n    seen.add(r["id"])\n    if r["status"] not in {"paid","canceled"}: errors.append("status")\n    if type(r["cents"]) is not int or r["cents"]<0: errors.append("amount")\nprint(errors)',expect:"['duplicate_id', 'status', 'amount']",limit:'These checks detect the stated contract violations only. Passing records can still contain incorrect amounts, omitted events or misleading business definitions.',mistakes:['A parsing success does not establish business accuracy.','Silently deleting invalid rows changes population coverage.'],takeaways:['Turn important assumptions into explicit checks.','Preserve raw evidence and report what was excluded.'],practice:[
['What belongs in a data contract?','Grain, types and units','Only a filename','Only the company logo','Only a chart title','A contract makes producer/consumer assumptions explicit and checkable.'],
['Does passing validation prove every record is true?','No','Yes universally','Only for integer fields','Only if no values are missing','Validation checks defined constraints, not every possible real-world fact or collection failure.'],
['Should raw records be silently rewritten to make checks pass?','No','Yes by default','Only if the file is small','Only if a chart is needed','Corrections need traceable policy; silent rewriting hides evidence and can introduce bias.'],
['A pipeline drops 30% of rows as invalid. What must a report reveal?','Coverage and exclusions','Only the final average','Only successful row count','Only the output checksum','Exclusion can change who is represented, so usable coverage and reasons are material to interpretation.'],
['An amount check accepts True as one cent. What Python nuance matters?','bool subclasses int','Every boolean is missing','Integers cannot be validated','Currencies require strings only','A strict integer monetary field may need type(value) is int rather than isinstance(value,int).'],
['A producer changes cents to dollars without renaming a field. What is broken?','The unit contract','Only the sort order','Only the row count','Only CSV quoting','A semantic schema change can preserve parseability while changing every numeric interpretation.'],
['A status value is unfamiliar. What should happen?','Flag for reviewed handling','Assume it means success','Replace it randomly','Delete all statuses','Unknown categories require an explicit handling decision, not an invented business meaning.']
],formal:[
['Why test key uniqueness?','To check row grain','To prove every field true','To remove all missing data','To infer causal effects','A duplicate key can contradict a one-record-per-entity/event contract and corrupt aggregation.'],
['What is quarantine in a data pipeline?','Separate flagged records for review','Delete every unusual value forever','Change every value to zero','Publish raw errors to everyone','Quarantine isolates problematic evidence while preserving it for diagnosis under controlled access.'],
['What does a range check establish?','Compliance with that range rule','Complete business correctness','Universal representativeness','Causal identification','A value can satisfy a numeric range and still be wrong, mismeasured or irrelevant.'],
['A batch changes status definitions but keeps the same strings. What should be versioned?','Semantic field definitions','Only export font settings','Only filename capitalization','Only chart colors','Consumers need to know when the meaning of apparently unchanged values changes.'],
['A report excludes invalid timestamps without disclosure. What is at risk?','Population/time coverage','The existence of valid dates','Only report page count','Only decimal formatting','Invalid-time exclusions may systematically remove groups or periods and change the answer.'],
['A validator auto-casts every malformed amount to zero. Why is that risky?','It turns unknowns into facts','It guarantees unbiased totals','It preserves every meaning','It proves the amount was absent','Zero is a meaningful amount; replacing malformed values invents observations and distorts aggregates.'],
['A consumer expects integer cents but receives decimal dollars. What is needed?','A contract change','Only a wider column','Only a new row id','Only a faster query','Both representation and units differ, requiring explicit conversion/versioning and review.'],
['A dataset passes key, type and status checks but omits a region. What remains?','A coverage limitation','A complete population proof','Guaranteed unbiased estimates','No further assumptions','Structural checks do not discover every missing part of the target population.'],
['An analyst corrects a known source error. What supports accountability?','A logged reproducible correction','Only editing the final slide','Only deleting the raw value','Only hiding failed checks','Documented rules and preserved original evidence allow the correction to be reviewed and reproduced.'],
['A team calls a validator a truth engine. Which distinction should be taught?','Validity versus accuracy','Integers versus column names only','Charts versus spreadsheets only','CSV versus JSON only','Defined rules can detect violations but cannot establish all semantic, collection and real-world truth conditions.']
]},
{id:'dbf-metric',comps:['m3.c1'],title:'Define numerator, denominator and reporting window',intro:'A conversion rate is not complete until “conversion,” “eligible opportunity” and the reporting period are specified. Different reasonable definitions can produce different numbers from the same records.',sections:[['Write a metric specification','Specify the decision purpose, entity/grain, numerator event, denominator population, inclusion/exclusion rules, time basis, unit and owner. A completed-order conversion rate per eligible session differs from a purchase rate per distinct user. State whether repeated events count once or multiple times.','Align numerator and denominator cohorts and time windows. Purchases in November divided by signups in November is not automatically the conversion rate of November signups, because some purchases belong to earlier cohorts and some new signups convert later. A cohort window can make the intended follow-up explicit.'],['Ratios need valid denominators','A ratio’s numerator should correspond to its declared denominator population. When the denominator is zero, return an explicit undefined/no-opportunity state rather than zero or infinity without explanation. Aggregate rates by combining appropriate counts; averaging subgroup rates equally can mislead when denominators differ.','The fixture computes a purchase rate for a fixed eligible-session cohort and distinguishes a zero-denominator case. It verifies a calculation under declared counts, not eligibility correctness or causal effect of a product change.']],problem:'Calculate an eligible-session conversion rate with a zero-denominator policy.',steps:['Use matched numerator and denominator definitions.','Reject counts outside the ratio contract.','Return a distinct missing rate when there are no opportunities.'],code:'def conversion(purchases,eligible):\n    if not 0 <= purchases <= eligible: raise ValueError("invalid counts")\n    return None if eligible==0 else purchases/eligible\nprint(conversion(12,100))\nprint(conversion(0,0))',expect:'0.12\nNone',limit:'The function checks its count contract only. It cannot prove that source events, identity resolution or eligibility definitions match the business question.',mistakes:['A zero denominator is not the same as a measured zero rate.','Combining numerator and denominator from unrelated cohorts changes the question.'],takeaways:['A metric is a versioned definition, not only a formula.','Make denominator and follow-up rules explicit.'],practice:[
['What must accompany a conversion numerator?','An eligible denominator','Only a chart title','Only a currency symbol','Only a row sort order','The rate’s meaning depends on which opportunities or entities are counted in its denominator.'],
['What is an appropriate output when there are zero eligible opportunities?','An explicit undefined state','A measured zero conversion','Guaranteed full conversion','An arbitrary population rate','No observed opportunities means the rate cannot be estimated from those counts.'],
['Are user conversion and session conversion identical definitions?','No','Yes universally','Only if rounded','Only when stored together','A user can have multiple sessions, so entity grain changes both denominator and interpretation.'],
['November purchases are divided by November signups. What should be checked?','Cohort and follow-up alignment','Only calendar spelling','Only the chart width','Only the signup column type','Purchases may belong to earlier signups, and new signups may convert later.'],
['One campaign has 1/2 conversions and another 90/100. What is the combined rate?','91/102','70%','91%','92/102','Combine corresponding successes and opportunities before division rather than averaging rates equally.'],
['A team changes eligibility rules but compares rates as if unchanged. What is needed?','Definition versioning','Only a refreshed logo','Only fewer decimal places','Only another line color','A changed denominator population can move the rate without a change in underlying behavior.'],
['A numerator count exceeds eligible sessions under a one-conversion-per-session definition. What is indicated?','A contract violation','A valid rate above one','Automatic business success','A harmless display issue','Under that declared ratio contract the numerator must be bounded by the eligible denominator.']
],formal:[
['Which element defines a rate’s reference population?','Denominator','Chart title','File size','Sort key','The denominator states which opportunities/entities the numerator is measured relative to.'],
['What is a cohort?','A shared-entry group','Every row with a number','Only the newest customer','A metric without a denominator','A cohort groups units by a specified starting condition, often for aligned follow-up.'],
['What does a metric unit clarify?','The measurement scale','Only chart color','Only database engine','Only account names','Units distinguish counts, money, duration, proportions and other measured quantities.'],
['A clinic compares appointments completed per doctor-day across sites. What needs alignment?','Doctor-day definition','Only site-id spelling','Only report font','Only maximum row length','A common denominator definition is required for interpretable productivity comparisons.'],
['A dashboard converts undefined rates to zero. What is lost?','No data versus poor rate','The ability to display a number','All positive observations','The column name','Zero opportunities do not provide a measured failure rate; conflation misleads decision owners.'],
['A product counts repeat purchases in the numerator but unique buyers in the denominator. What should be stated?','A different ratio meaning','That the rate must be below one','That repeats are impossible','That users equal purchases','Multiple events per user produce a different metric, such as purchases per buyer, rather than binary conversion.'],
['A school tracks pass rate by exam date but enrollment by signup date. What should be reviewed?','Temporal population alignment','Only the date string format','Only the graph title','Only department colors','Different time bases can place unrelated cohorts in numerator and denominator.'],
['A company changes cancellation handling midway through a trend. What supports interpretation?','Versioned metric rules','Only a continuous line','Only dropping annotations','Only more decimal places','A definition change can create a break in comparability and should be recorded and communicated.'],
['A manager asks for a metric’s owner. Why does it matter?','Definition stewardship','Guaranteed favorable outcomes','Authority to change every record','Only report branding','An owner can maintain the definition, resolve changes and coordinate consumers under governance.'],
['A precise formula uses inaccurate eligibility data. What remains necessary?','Source-quality validation','Only a faster calculator','Only exact rational arithmetic','Only an extra chart','Correct arithmetic cannot repair a denominator that misrepresents the intended population.']
]},
{id:'dbf-indicators',comps:['m3.c2'],title:'Distinguish leading signals from lagging outcomes',intro:'A subscription business wants to reduce churn. Past cancellations are an outcome measure; onboarding completion may be an earlier signal. Earlier does not automatically mean causal or reliable.',sections:[['Timing and decision usefulness','A lagging indicator describes an outcome after it occurs, such as completed sales or monthly churn. A leading indicator is available earlier and may help anticipate or influence a later outcome, such as setup completion or queue backlog. The classification depends on the decision horizon and process.','Validate the relationship over relevant populations and periods. A leading signal can lose predictive value after a policy or product change. Correlation with future outcomes does not prove that optimizing the signal will improve the outcome.'],['Avoid proxy gaming and one-metric control','A team measured only by ticket closures may close tickets prematurely. A conversion target without refund/quality guardrails can reward low-quality purchases. Use outcome metrics and guardrails alongside process indicators, and examine whether behavior changes in response to the metric.','The fixture separates early engagement signals from later observed retention and computes an association by signal group. It shows how an indicator can be evaluated descriptively, not that changing the signal causes retention or that the tiny sample supports prediction.']],problem:'Compare later retention for two synthetic early-signal groups.',steps:['Define the early signal separately from the outcome.','Group eligible users by their signal.','Report outcomes and denominators without a causal claim.'],code:'rows=[(True,1),(True,1),(True,0),(False,0),(False,1)]\nfor flag in [True,False]:\n    y=[r for s,r in rows if s==flag]\n    print(flag,sum(y),len(y))',expect:'True 2 3\nFalse 1 2',limit:'The counts show an association in five synthetic users. They do not establish causation, prediction reliability or a useful intervention target.',mistakes:['A leading indicator is not automatically a causal lever.','Optimizing a proxy can damage the real outcome if incentives encourage gaming.'],takeaways:['Choose indicators relative to a process and decision horizon.','Validate signals and retain outcome/quality guardrails.'],practice:[
['Which is a lagging outcome for subscription retention?','Observed cancellations','A new onboarding click','A planned reminder','A forecasted warning','Cancellations record an outcome after it occurs rather than an earlier process signal.'],
['Does an early correlated signal automatically identify an intervention?','No','Yes by timing alone','Only if it is numeric','Only if it has a name','Temporal order and correlation alone do not prove changing the signal will cause the desired outcome.'],
['Why include guardrails?','To monitor constraints','To remove every tradeoff','To guarantee causality','To avoid measuring outcomes','Guardrails can reveal adverse effects hidden by optimizing one primary metric.'],
['Agents are rewarded only for closing tickets and begin closing unresolved cases. What happened?','Proxy gaming','Perfect service improvement','A missing date parser','Guaranteed customer satisfaction','The incentive improves the recorded proxy while undermining the underlying support objective.'],
['An onboarding signal predicts retention in old cohorts but not new ones. What should be reviewed?','Relationship drift','Only chart colors','Only column order','Only old file size','Process, population or measurement changes can alter a signal’s predictive relationship.'],
['A queue backlog is leading for tomorrow’s delay but lagging for yesterday’s staffing. What does this show?','Classification depends on horizon','Indicators have no meaning','Every measure is always leading','Every measure is always lagging','Whether a metric precedes the relevant outcome depends on the decision and process being considered.'],
['A sales incentive increases purchases and refunds. What should be assessed?','Net value and guardrails','Only gross purchase count','Only the largest uplift','Only agent rankings','A primary metric can improve while business value or customer outcomes worsen.']
],formal:[
['What is a leading indicator?','An earlier outcome signal','A guaranteed cause','Always the largest metric','Only a financial total','A leading indicator arrives before the outcome and may inform prediction or action, subject to validation.'],
['What is a lagging indicator?','A realized outcome','Any forecast','Any planned action','Any missing value','Lagging measures describe results after the relevant process or event.'],
['What is proxy gaming?','Metric/objective mismatch','Calculating a valid mean','Measuring a true outcome','Using a known denominator','Behavior can optimize a measured proxy in ways that undermine the actual goal.'],
['A logistics firm tracks loading readiness before departure. What makes it potentially leading?','It precedes the outcome','It is always causal','It uses a percentage','It is easy to display','Timing and a relevant validated relationship can make readiness an early operational signal.'],
['A bank uses application clicks as its only quality target. What is missing?','Outcome and harm validation','Only a larger click total','Only a faster dashboard','Only another button color','Clicks may not capture suitable completed applications, customer harm or long-term value.'],
['An analyst calls historical revenue a leading metric for a decision about last month. What should be clarified?','The decision horizon','Only currency formatting','Only column width','Only file compression','Leading/lagging is relative to the process and outcome timeline, not a permanent label for every use.'],
['A signal improves after staff learn the target, but retention does not. What should be investigated?','Proxy/incentive effects','Automatic causal success','A guaranteed retention delay','Only chart rounding','Targeting a proxy can change how it is generated and break its earlier relationship with the desired outcome.'],
['A service predicts delays from backlog. What should be monitored over time?','Predictive/process drift','Only the original correlation','Only the metric name','Only old dashboard screenshots','Leading relationships can drift as operations, populations or instrumentation change.'],
['A product team wants to optimize one engagement measure without guardrails. What is a risk?','Hidden adverse outcomes','Guaranteed customer benefit','Automatic cost reduction','A valid causal experiment','A single proxy may rise while quality, cost, accessibility or other important outcomes deteriorate.'],
['An early indicator is associated with better outcomes in observational data. Which claim is justified without more design?','An observed association','A proven intervention effect','A guaranteed policy benefit','An unbiased causal coefficient','The data can show a relationship but not automatically identify what would happen if the indicator were manipulated.']
]},
{id:'dbf-scorecard',comps:['m3.c1','m3.c2'],title:'Build a decision scorecard with definitions and safeguards',intro:'A practical scorecard combines a business outcome, a useful process signal and guardrails, each with an owner and a clear definition. It should make tradeoffs visible rather than reduce every decision to a single colored badge.',sections:[['Connect measures without collapsing their meaning','For a support redesign, an outcome might be repeat-contact rate within seven days; a process indicator might be first-response time; guardrails might include unresolved closure rate and staff overtime. Specify population, period, direction and data source for each measure.','A low response time is not valuable if responses are unhelpful. A high closure count is not success if cases reopen. Review the joint pattern and qualitative context before action. Avoid adding incompatible units into one arbitrary score unless the weighting/value model is explicitly justified.'],['Make the scorecard reviewable and maintainable','Include definitions, owners, refresh cadence, coverage and known limitations. Distinguish no data from a breached target, and flag definition changes before comparing trends. Provide the decision owner with the evidence and tradeoffs needed to act under the organization’s actual policy.','The fixture evaluates declared toy thresholds for benefit and harm separately. It deliberately produces a review-required state when the primary outcome passes but a guardrail fails. This is a transparent decision rule illustration, not a universal release policy or substitute for statistical evidence.']],problem:'Keep a guardrail failure visible when a primary metric meets its target.',steps:['Evaluate the primary metric against its declared target.','Evaluate the quality guardrail separately.','Require review rather than collapsing the result into a success label.'],code:'metrics={"repeat_contact_rate":0.08,"unresolved_closure_rate":0.06}\nprimary_ok=metrics["repeat_contact_rate"]<=0.10\nguardrail_ok=metrics["unresolved_closure_rate"]<=0.02\nprint(primary_ok,guardrail_ok)\nprint("eligible_for_review" if primary_ok and guardrail_ok else "review_required")',expect:'True False\nreview_required',limit:'Threshold checks expose the stated toy tradeoff. They do not quantify uncertainty, establish causation or approve a real operational change.',mistakes:['An attractive primary metric can hide a breached harm constraint.','A composite score with unexplained units and weights can obscure the decision.'],takeaways:['Use complementary outcome, process and guardrail measures.','Make ownership, uncertainty and no-data states visible.'],practice:[
['What should a scorecard connect?','Outcomes and guardrails','Only the largest favorable number','Only employee rankings','Only raw record counts','Complementary measures expose benefits, operational signals and adverse effects relevant to a decision.'],
['Should a primary target automatically override a failed guardrail?','No','Yes by definition','Only if the chart is green','Only if the metric is numeric','Guardrails represent important constraints/harms and require the specified review policy.'],
['Why avoid an unexplained sum of minutes and dollars?','Unjustified units/weights','Addition cannot be coded','Every composite is forbidden','The values must be strings','A composite needs a justified value/weighting model rather than arbitrary arithmetic on incompatible units.'],
['A scorecard has no observations for a metric. What should it show?','An explicit no-data state','An automatic passed target','An automatic zero outcome','A random previous value','No evidence should remain distinct from observed performance and be handled under a documented policy.'],
['A support redesign reduces first-response time but increases repeat contacts. What is needed?','Joint outcome interpretation','Only the faster response headline','Only a larger closure total','Only the process metric','The combined pattern may indicate less helpful responses despite a faster initial action.'],
['A metric definition changes after a system migration. How should trends be treated?','Annotate/reconcile comparability','Continue silently as identical','Delete all prior history','Invent matching old values','Definition changes can create artificial trend breaks that need explicit explanation or reconciliation.'],
['A threshold check passes on five users. What remains necessary?','Appropriate evidence and review','Automatic production approval','A universal causal claim','A guarantee for every region','Threshold arithmetic alone does not establish sampling precision, generalization or the right business decision.']
],formal:[
['What makes a scorecard actionable?','Decision-linked measures','Only more charts','Only brighter colors','Only frequent refreshes','Metrics need purpose, definitions, owners and interpretation linked to an available decision.'],
['Why record refresh cadence?','To interpret evidence timeliness','To prove every value accurate','To remove every bias','To guarantee metric improvement','Readers need to know when source observations and calculations were last updated.'],
['What is a guardrail breach?','An unmet constraint','A guaranteed arithmetic bug','A missing title only','A forced business success','A breached guardrail signals a relevant harm/constraint requiring action under the decision policy.'],
['A retail scorecard shows sales up and returns sharply up. What should be assessed?','Net value and quality impact','Only sales growth','Only the largest percentage','Only transaction count','Sales alone may conceal low-quality transactions, added costs or customer harm.'],
['A clinic combines waiting minutes and satisfaction stars with arbitrary equal weights. What needs justification?','The composite value model','Only the spreadsheet formula syntax','Only star icon design','Only rounding precision','Different units and meanings cannot be combined interpretably without a reasoned scaling/weighting model.'],
['A reporting pipeline fails, and every missing metric is colored green. What is wrong?','No-data is treated as success','The chart has too many colors','The metric is necessarily zero','The targets are automatically met','Evidence absence must be distinguished from observed compliance with targets.'],
['An operations team improves a process signal while the outcome worsens. What should the scorecard enable?','Tradeoff investigation','Automatic celebration','Removal of the outcome','Only a renamed indicator','Complementary measures help detect proxy optimization or unintended effects.'],
['An old metric version is compared with a new one after eligibility changes. What is required?','Definition-change disclosure','Only the same line color','Only a bigger axis','Only a common file suffix','Different populations/rules can produce noncomparable values despite matching metric names.'],
['A manager wants to rank teams from very small unequal denominators. What should be visible?','Counts and uncertainty','Only percentages','Only team names','Only the top rank','Small denominators produce unstable rates; counts, context and uncertainty limit overinterpretation.'],
['A scorecard rule returns review-required after a guardrail failure. What does this establish?','The declared rule was applied','A final release decision is proved','The intervention is causal','Every source field is accurate','A transparent rule check is one step; real decisions still need valid evidence, governance and context.']
]}
];
module.exports=course('data-business-fundamentals',specs,['collections','decimal']);
